const MHAIR={m_buzz:{n:"Buzz cut",x:37.11,y:12.45,w:26.04,h:17.79,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_quiff:{n:"Hacimli geriye",x:36.49,y:9.41,w:26.78,h:21.45,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_slick:{n:"Geriye taranmış (jöleli)",x:36.73,y:11.83,w:26.78,h:18.91,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_side:{n:"Yandan ayrık",x:36.61,y:11.45,w:26.78,h:19.1,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_messy:{n:"Dağınık orta boy",x:33.01,y:9.22,w:34.53,h:23.62,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_curtain:{n:"Perde kesim",x:35.06,y:10.4,w:30.19,h:20.46,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_mullet:{n:"Mullet",x:35.74,y:10.71,w:28.46,h:38.32,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_twist:{n:"Twist",x:36.11,y:11.52,w:27.71,h:18.35,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_dread:{n:"Dread",x:30.84,y:11.27,w:38.25,h:34.91,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"},m_mohawk:{n:"Mohawk",x:41.14,y:9.16,w:17.24,h:11.84,sil:"data:image/webp;base64,",det:"data:image/webp;base64,"}};
function mhairFront(k,c){const H=MHAIR[k],id='mh'+(++uid);return `<defs><mask id="${id}"><image href="${H.sil}" x="${H.x}" y="${H.y}" width="${H.w}" height="${H.h}" preserveAspectRatio="none"/></mask></defs><rect x="${H.x}" y="${H.y}" width="${H.w}" height="${H.h}" fill="${c}" mask="url(#${id})"/><image href="${H.det}" x="${H.x}" y="${H.y}" width="${H.w}" height="${H.h}" preserveAspectRatio="none"/>`}
Object.keys(MHAIR).reverse().forEach(k=>{HAIR3[k]={n:MHAIR[k].n,g:'e',back:null,front:c=>mhairFront(k,c)};if(!HAIR_E.some(x=>x[0]===k))HAIR_E.unshift([k,MHAIR[k].n])});
/* kaldırılan eski saçlar → yeni karşılıkları */
const MHAIR_DEL={"crew": "m_buzz", "quiff": "m_quiff", "slick": "m_slick", "sidepart": "m_side", "messy": "m_messy", "curtain": "m_curtain", "mullet": "m_mullet", "twist": "m_twist", "dread": "m_dread", "mohawk": "m_mohawk"};
Object.keys(MHAIR_DEL).forEach(k=>{const i=HAIR_E.findIndex(x=>x[0]===k);if(i>=0)HAIR_E.splice(i,1)});
{const _AV0=AV;AV=function(L,age,opts){if(L&&L.g!=='k'&&MHAIR_DEL[L.hair]&&MHAIR[MHAIR_DEL[L.hair]])L.hair=MHAIR_DEL[L.hair];return _AV0(L,age,opts)}}
